import{_ as a,o as e,a as i,b as n}from"./app.C41L12d5.js";const _="/ascendc.github.io/assets/nd_no_32.BtryVHJB.png",l="/ascendc.github.io/assets/nd_32_align.BK7tnP1Q.png",p="/ascendc.github.io/assets/nd_align_32.B_i92KOT.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矩阵编程（高阶API）","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/matrix_advanced_api"},{"text":"特性场景","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_features"},{"text":"矩阵乘输出的N方向对齐","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_output_n_alignment"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_output_n_alignment.md","filePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_output_n_alignment.md","outlineHeaders":[{"level":2,"title":"功能介绍","slug":"功能介绍","link":"#功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景","link":"#使用场景"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787050286000}'),o={name:"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_output_n_alignment.md"};function s(r,t,c,m,d,u){return e(),i("div",null,[...t[0]||(t[0]=[n('<div><article class="markdown-body"><h1>矩阵乘输出的N方向对齐<span id="ZH-CN_TOPIC_0000002532228169"></span></h1><h2 id="功能介绍">功能介绍<span id="zh-cn_topic_0000002265055666_section310824820358"></span><a class="header-anchor" href="#功能介绍">​</a></h2><p>矩阵乘输出的N方向对齐，即矩阵乘结果C矩阵按ND_ALIGN格式输出。在Matmul矩阵乘法中，常用的矩阵数据格式有ND、NZ，相关介绍可参考<a href="../basics.html#zh-cn_topic_0000001622194138_section1453415011">数据格式</a>章节。ND_ALIGN是矩阵的另一种数据格式，该格式一般用于N方向非32字节对齐的矩阵乘计算中，配置结果C矩阵为ND_ALIGN格式后，将按照N方向32字节对齐的补齐规则输出C矩阵，详细内容请见<a href="../../../../technical_appendix/concepts_and_terms/neural_networks_and_operators/data_layout.html#li075920427155">ND_ALIGN</a>。</p><p>以M=16，K=16，N=14，A、B矩阵数据类型为half的Matmul为具体示例，说明ND_ALIGN输出功能。当配置C矩阵为ND格式并输出到Global Memory时，按照原始N方向大小非32字节对齐输出如<a href="#zh-cn_topic_0000002265055666_fig2311855162511">图1</a>所示。当配置C矩阵为ND格式时，按照N方向32字节对齐输出如<a href="#zh-cn_topic_0000002265055666_fig25741012182719">图2</a>所示，C矩阵的N方向最后两列由下一行的实际数据进行填充补齐，以实现N方向对齐到32字节并输出。当配置C矩阵为ND_ALIGN格式时，Matmul API会在C矩阵的N方向上通过添加无效数据来填充最后两列，以确保N方向对齐至32字节并输出，如<a href="#zh-cn_topic_0000002265055666_fig4840114152818">图3</a>所示。</p><p><strong>图1</strong> ND格式C矩阵N方向非32字节对齐示意图<span id="zh-cn_topic_0000002265055666_fig2311855162511"></span><br><img src="'+_+'" alt title="ND格式C矩阵N方向非32字节对齐示意图"></p><p><strong>图2</strong> ND格式C矩阵N方向32字节对齐示意图<span id="zh-cn_topic_0000002265055666_fig25741012182719"></span><br><img src="'+l+'" alt title="ND格式C矩阵N方向32字节对齐示意图"></p><p><strong>图3</strong> ND_ALIGN格式C矩阵N方向32字节对齐示意图<span id="zh-cn_topic_0000002265055666_fig4840114152818"></span><br><img src="'+p+`" alt title="ND_ALIGN格式C矩阵N方向32字节对齐示意图"></p><h2 id="使用场景">使用场景<span id="zh-cn_topic_0000002265055666_section118051016163613"></span><a class="header-anchor" href="#使用场景">​</a></h2><p>Matmul计算中N方向非32字节对齐，输出C矩阵的N方向要求32字节对齐的场景。</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002265055666_section14160134220363"></span><a class="header-anchor" href="#约束说明">​</a></h2><p>若配置C矩阵为ND_ALIGN格式输出，则为C矩阵申请的Buffer空间为N向上32字节对齐后的空间大小。</p><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002265055666_section15486294368"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_format_nd_align">matmul_nd_align算子样例</a>。</p><ul><li><p>Tiling实现</p><p>调用SetCType接口，设置C矩阵的数据格式为CubeFormat::ND_ALIGN，其它Tiling实现与<a href="../operator_impl.html">基础场景</a>相同。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());
matmul_tiling::MatmulApiTiling tiling(ascendcPlatform); 
tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16); 
tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);  
// 设置C矩阵，buffer位置为GM，数据格式为ND_ALIGN
tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND_ALIGN, matmul_tiling::DataType::DT_FLOAT);
tiling.SetBiasType(AscendC::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
... // 其他实现内容
optiling::TCubeTiling tilingData;   
int ret = tiling.GetTiling(tilingData);
</code></pre></div></li><li><p>核函数（Kernel）实现</p><p>相较于<a href="../operator_impl.html#zh-cn_topic_0000001622514006_li1032116474330">基础场景</a>，ND_ALIGN输出功能要求在创建Matmul对象时，设置模板参数cType的数据格式为CubeFormat::ND_ALIGN。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>#include &quot;lib/matmul_intf.h&quot;

typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; aType; 
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; bType; 
// 设置模板参数cType的数据格式为ND_ALIGN
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND_ALIGN, float&gt; cType; 
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; biasType; 
AscendC::Matmul&lt;aType, bType, cType, biasType&gt; mm;
</code></pre></div></li></ul></article></div>`,1)])])}const N=a(o,[["render",s]]);export{g as __pageData,N as default};
